// ---------- 启动页 ----------
window.addEventListener('load', function () {
  const splash = document.getElementById('splash');
  if (!splash) return;
  if (sessionStorage.getItem('jianji_splash_shown')) { splash.remove(); return; }
  sessionStorage.setItem('jianji_splash_shown', '1');
  setTimeout(function () {
    splash.classList.add('fade');
    setTimeout(function () { splash.remove(); }, 560);
  }, 1950);
});

