// 柔和莫兰迪调色板（分类构成用，低饱和、互异）——浅色 / 深色两套
const CHART_COLORS_LIGHT = ['#D89A86', '#8FAED1', '#E2BF84', '#BEA6CC', '#85BEAB', '#E0A2B0', '#7EA6CB', '#8FBDB4', '#A7A08F', '#C9B16E'];
const CHART_COLORS_DARK = ['#DDA894', '#9BB9DA', '#E7C992', '#C8B2D4', '#92C7B5', '#E5AFBB', '#8BB2D4', '#9CC6BE', '#B2AC9C', '#D2BB79'];
// 分类名 → 固定柔和色（保证同分类始终同色、且互有区分）
const CATEGORY_COLORS = {
  '餐饮': '#D89A86', '交通': '#8FAED1', '购物': '#E2BF84', '娱乐': '#BEA6CC',
  '居住': '#85BEAB', '医疗': '#E0A2B0', '教育': '#7EA6CB', '通讯': '#8FBDB4',
  '其他': '#A7A08F',
  '工资': '#7E9E8F', '奖金': '#B7C96E', '兼职': '#93B48A', '理财': '#C9AF6B',
  '红包': '#E08B7E', '退款': '#82A5BF', '其他收入': '#A89B6F'
};
const CATEGORY_COLORS_DARK = {
  '餐饮': '#DDA894', '交通': '#9BB9DA', '购物': '#E7C992', '娱乐': '#C8B2D4',
  '居住': '#92C7B5', '医疗': '#E5AFBB', '教育': '#8BB2D4', '通讯': '#9CC6BE',
  '其他': '#B2AC9C',
  '工资': '#8BA99B', '奖金': '#C2D17E', '兼职': '#9FBE97', '理财': '#D2BB7B',
  '红包': '#E59A8E', '退款': '#8FB1C8', '其他收入': '#B3A77E'
};
function catColor(name) {
  const dark = isDarkTheme();
  const table = dark ? CATEGORY_COLORS_DARK : CATEGORY_COLORS;
  if (table[name]) return table[name];
  // 未知分类：按名称稳定散列到柔和调色板
  const palette = dark ? CHART_COLORS_DARK : CHART_COLORS_LIGHT;
  let h = 0;
  for (let k = 0; k < name.length; k++) h = (h * 31 + name.charCodeAt(k)) >>> 0;
  return palette[h % palette.length];
}

// ============================================================
// 主题（宣纸 / 夜墨）
// ============================================================
const THEME_KEY = 'jianji_theme';                     // 'auto' | 'light' | 'dark'
const THEME_COLOR = { light: '#F4F0E6', dark: '#1B1813' };
const mqDark = window.matchMedia ? window.matchMedia('(prefers-color-scheme: dark)') : null;

function getThemePref() {
  const v = localStorage.getItem(THEME_KEY);
  return (v === 'light' || v === 'dark') ? v : 'auto';
}

function resolveTheme(pref) {
  if (pref === 'light' || pref === 'dark') return pref;
  return (mqDark && mqDark.matches) ? 'dark' : 'light';
}

function currentTheme() {
  return document.documentElement.getAttribute('data-theme') === 'dark' ? 'dark' : 'light';
}

function isDarkTheme() {
  return currentTheme() === 'dark';
}

// 应用主题：写 data-theme → 同步状态栏配色 → 同步设置页 UI
function applyTheme(pref) {
  const p = pref || getThemePref();
  const theme = resolveTheme(p);
  document.documentElement.setAttribute('data-theme', theme);
  const meta = document.querySelector('meta[name="theme-color"]');
  if (meta) meta.setAttribute('content', THEME_COLOR[theme]);
  syncThemeUI(p);
  return theme;
}

function setThemePref(pref) {
  localStorage.setItem(THEME_KEY, pref);
  applyTheme(pref);
  // 图表色随主题切换 → 重绘当前页
  if (currentPage === 'stats') loadStatsData();
  else if (currentPage === 'home') renderHome();
  else pushWidgetStats();
}

function syncThemeUI(pref) {
  const p = pref || getThemePref();
  document.querySelectorAll('#themeSeg button').forEach(b => {
    b.classList.toggle('active', b.dataset.themePref === p);
  });
  const el = document.getElementById('themeHint');
  if (el) {
    const sys = resolveTheme('auto') === 'dark' ? '深色' : '浅色';
    el.textContent = p === 'auto' ? `跟随系统（当前系统为${sys}）`
      : (p === 'dark' ? '始终使用夜墨主题' : '始终使用宣纸主题');
  }
}

function initTheme() {
  applyTheme(getThemePref());
  // 系统主题变化时，仅在「跟随系统」下实时切换
  if (mqDark && mqDark.addEventListener) {
    mqDark.addEventListener('change', () => {
      if (getThemePref() !== 'auto') return;
      applyTheme('auto');
      if (currentPage === 'stats') loadStatsData();
      else if (currentPage === 'home') renderHome();
    });
  }
}

// 读取当前主题下的 CSS 变量值（Canvas 绘图用）
function cssVar(name, fallback) {
  const v = getComputedStyle(document.documentElement).getPropertyValue(name).trim();
  return v || fallback || '';
}

