// 从任意平台描述中识别已知平台（如"淘宝订单"→"淘宝"）
function detectPlatform(name) {
  if (!name) return null;
  const s = String(name);
  for (const key of ['纸质小票', '微信', '支付宝', '淘宝', '京东', '拼多多']) {
    if (s.includes(key)) return key;
  }
  return null;
}

// 整图标尺寸的平台 logo（无平台或未知平台时返回占位方块 logo）
function platformLogoHtml(platform, cls) {
  const key = detectPlatform(platform);
  const m = key ? PLATFORM_LOGOS[key] : null;
  const c = cls ? ` ${cls}` : '';
  if (m) return `<span class="pl-logo${c}" title="${key}">${m.svg}</span>`;
  const s = String(platform || '').trim();
  const ch = escapeHtml([...s][0] || '?');
  return `<span class="pl-logo${c}" title="${escapeHtml(s)}"><svg viewBox="0 0 24 24"><rect width="24" height="24" rx="5.5" fill="#8A8371"/><text x="12" y="13.4" text-anchor="middle" dominant-baseline="central" font-size="12" font-weight="700" fill="#fff" font-family="'PingFang SC','Microsoft YaHei',sans-serif">${ch}</text></svg></span>`;
}

// ---------- 工具 ----------
function escapeHtml(s) {
  return String(s ?? '').replace(/[&<>"']/g, ch =>
    ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[ch]));
}

// 获取分类的图标 id（数据层存的 id 或旧 Emoji）
function getCategoryIcon(name) {
  const cat = getCategories().find(c => c.name === name)
    || getIncomeCategories().find(c => c.name === name);
  return cat ? cat.icon : 'misc';
}

// 渲染分类图标 HTML：优先用定制 SVG，旧 Emoji 数据原样显示
function renderCatIcon(name) {
  return catIconHtml(getCategoryIcon(name), name);
}

// 空状态（V6）：墨线账本插画 + 文案 + 行动按钮；compact 用于统计小面板（无插画无按钮）
function emptyStateHtml(msg, action, compact) {
  const art = compact ? '' : `
    <svg class="es-art" viewBox="0 0 96 72" fill="none" stroke="currentColor" stroke-width="2.4" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">
      <rect x="22" y="10" width="52" height="52" rx="7"/>
      <path d="M22 24h52"/>
      <path d="M33 17h11"/>
      <path d="M35 41c4.5-6.5 10-8.5 15-5.5s9 2.5 13-3.5"/>
      <path d="M34 53h20" stroke-opacity=".4"/>
    </svg>`;
  const btn = action ? `<button type="button" class="es-cta" onclick="navigateTo('add')">${action}</button>` : '';
  return `<div class="empty-state${compact ? ' compact' : ''}">${art}<p>${escapeHtml(msg)}</p>${btn}</div>`;
}

function isIncome(t) {
  return t.flow === 'income';
}

function sumBy(list, fn) {
  return list.reduce((s, x) => s + (fn ? fn(x) : x), 0);
}

function fmtMoney(n) {
  return Number(n || 0).toFixed(2);
}

function showToast(msg) {
  const t = document.getElementById('toast');
  t.textContent = msg;
  t.classList.add('show');
  clearTimeout(t._timer);
  t._timer = setTimeout(() => t.classList.remove('show'), 2200);
}

// ---------- 导航 ----------
function navigateTo(page, subTab) {
  currentPage = page;
  document.querySelectorAll('.page').forEach(p => p.classList.remove('active'));
  document.getElementById(`page-${page}`).classList.add('active');

  document.querySelectorAll('.tab-item').forEach(n => n.classList.remove('active'));
  const tab = document.querySelector(`.tab-item[data-page="${page}"]`);
  if (tab) tab.classList.add('active');
  document.getElementById('tabAddBtn').classList.toggle('active', page === 'add');

  document.getElementById(`page-${page}`).scrollTop = 0;

  if (page === 'home') renderHome();
  else if (page === 'add') switchAddTab(subTab === 'auto' ? 'auto' : 'manual');
  else if (page === 'stats') renderStats();
  else if (page === 'bills') renderBills();
  else if (page === 'settings') renderSettings();
}

// ============================================================
// 首页
// ============================================================
function renderHome() {
  const today = getTodayStr();
  const todayTotal = sumBy(getTransactionsByDate(today).filter(t => !isIncome(t)), t => t.amount);
  const weekTotal = sumBy(getTransactionsByWeek(today).filter(t => !isIncome(t)), t => t.amount);
  const now = new Date();
  const monthTx = getTransactionsByMonth(now.getFullYear(), now.getMonth() + 1);
  const monthTotal = sumBy(monthTx.filter(t => !isIncome(t)), t => t.amount);
  const monthIncome = sumBy(monthTx.filter(isIncome), t => t.amount);

  document.getElementById('todayAmount').textContent = fmtMoney(todayTotal);
  document.getElementById('weekAmount').textContent = '¥' + Math.round(weekTotal);
  document.getElementById('monthAmount').textContent = '¥' + Math.round(monthTotal);
  document.getElementById('monthIncome').textContent = '¥' + Math.round(monthIncome);

  renderHomeFlow();
  pushWidgetStats();   // 同步桌面小组件数据
}

// ============================================================
// 账单流水（首页）：按日期/时间排序分组 + 无限下滑加载
// ============================================================
let homeFlowAll = [];      // 排序后的全量流水
let homeFlowIndex = 0;     // 已渲染到的下标
let homeFlowLastDate = null;
let homeFlowScrollEl = null;
let homeFlowScrollFn = null;
const HOME_FLOW_STEP = 15;
const HOME_FLOW_ROOT_OFFSET = 200;

function sortTxByDateTime(list) {
  return [...list].sort((a, b) => {
    const d = (b.date || '').localeCompare(a.date || '');
    if (d !== 0) return d;
    const t = (b.time || '').localeCompare(a.time || '');
    if (t !== 0) return t;
    return (b.createdAt || 0) - (a.createdAt || 0);
  });
}

function renderHomeFlow() {
  const listEl = document.getElementById('homeFlow');
  const endEl = document.getElementById('homeFlowEnd');
  detachHomeFlowScroll();

  homeFlowLastDate = null;
  homeFlowAll = sortTxByDateTime(getTransactions());
  listEl.innerHTML = '';
  if (!homeFlowAll.length) {
    listEl.innerHTML = emptyStateHtml('还没有账目，记下第一笔吧', '记一笔');
    endEl.style.display = 'none';
    return;
  }
  endEl.textContent = '';

  homeFlowIndex = 0;
  appendHomeFlow();
  observeHomeFlow();
  fillUntilScrollable();
}

function flowHeadHtml(date, items) {
  const exp = sumBy(items.filter(t => !isIncome(t)), t => t.amount);
  const inc = sumBy(items.filter(isIncome), t => t.amount);
  const d = new Date(date + 'T00:00:00');
  return `<div class="day-head"><span>${d.getMonth() + 1}月${d.getDate()}日 · 周${WEEK_CN[d.getDay()]}</span>` +
    `<span class="d-amt">${inc > 0 ? `<em class="income-val">+¥${fmtMoney(inc)}</em> · ` : ''}¥${fmtMoney(exp)}</span></div>`;
}

function appendHomeFlow() {
  const listEl = document.getElementById('homeFlow');
  const endEl = document.getElementById('homeFlowEnd');
  const batch = homeFlowAll.slice(homeFlowIndex, homeFlowIndex + HOME_FLOW_STEP);
  homeFlowIndex += batch.length;

  // homeFlowAll 已按日期降序，批次内按日期分组
  const groups = {};
  batch.forEach(t => { (groups[t.date] = groups[t.date] || []).push(t); });

  Object.keys(groups).sort().reverse().forEach(date => {
    const items = groups[date];
    if (date === homeFlowLastDate && homeFlowLastDate) {
      const panels = listEl.querySelectorAll('.day-panel');
      if (panels.length) panels[panels.length - 1].insertAdjacentHTML('beforeend', items.map(txRowHtml).join(''));
    } else {
      listEl.insertAdjacentHTML('beforeend',
        `<div class="day-group">${flowHeadHtml(date, items)}<div class="day-panel">${items.map(txRowHtml).join('')}</div></div>`);
      homeFlowLastDate = date;
    }
  });

  if (homeFlowIndex >= homeFlowAll.length) {
    endEl.textContent = '—— 已到底 ——';
    endEl.style.display = 'block';
    detachHomeFlowScroll();
  } else {
    endEl.textContent = '';
    endEl.style.display = 'block';
  }
}

// 滚动容器接近底部时加载下一批
function observeHomeFlow() {
  detachHomeFlowScroll();
  homeFlowScrollEl = document.getElementById('page-home');
  homeFlowScrollFn = onHomeFlowScroll;
  homeFlowScrollEl.addEventListener('scroll', homeFlowScrollFn, { passive: true });
}

// 首屏内容不足以产生滚动时，自动继续填充直到可滚动
function fillUntilScrollable() {
  const page = document.getElementById('page-home');
  let guard = 0;
  while (homeFlowIndex < homeFlowAll.length && page.scrollHeight <= page.clientHeight && guard < 50) {
    appendHomeFlow();
    guard++;
  }
}

function onHomeFlowScroll() {
  if (homeFlowIndex >= homeFlowAll.length) { detachHomeFlowScroll(); return; }
  const page = document.getElementById('page-home');
  if (page.scrollTop + page.clientHeight >= page.scrollHeight - HOME_FLOW_ROOT_OFFSET) {
    appendHomeFlow();
  }
}

function detachHomeFlowScroll() {
  if (homeFlowScrollEl && homeFlowScrollFn) {
    homeFlowScrollEl.removeEventListener('scroll', homeFlowScrollFn);
  }
  homeFlowScrollEl = null;
  homeFlowScrollFn = null;
}

function txRowHtml(t, opts = {}) {
  const icon = renderCatIcon(t.category);
  const title = t.subcategory || t.category;
  const sub = t.note || (t.items && t.items.length ? t.items.join('、') : t.category);
  const income = isIncome(t);
  const delAttr = opts.deleteId ? ` data-del="${opts.deleteId}"` : '';
  const clickTitle = opts.clickTitle ? ` title="${opts.clickTitle}"` : '';
  const typeTag = opts.showType && t.type === 'auto' ? ' <span class="muted">📷</span>' : '';
  // 有平台时整个图标位显示平台 logo，否则显示分类图标
  const ico = t.platform ? platformLogoHtml(t.platform) : icon;
  const icoCls = t.platform ? ' plat' : '';
  return `
    <div class="tx-row" data-tx="${t.id}"${delAttr}${clickTitle}>
      <div class="tx-ico${icoCls}">${ico}</div>
      <div class="tx-main">
        <div class="tx-title">${escapeHtml(title)}${typeTag}</div>
        <div class="tx-sub">${t.platform ? escapeHtml(t.platform) + ' · ' : ''}${escapeHtml(t.category)} · ${escapeHtml(sub)}</div>
      </div>
      <div class="tx-right">
        <div class="tx-amount fig ${income ? 'income-val' : ''}">${income ? '+' : ''}¥${fmtMoney(t.amount)}</div>
        <div class="tx-time">${escapeHtml(t.time || '')}</div>
      </div>
    </div>`;
}

