// 记账页
// ============================================================
function switchAddTab(tab) {
  document.querySelectorAll('#addSeg button').forEach(b => b.classList.toggle('active', b.dataset.tab === tab));
  document.querySelectorAll('#page-add .tab-content').forEach(c => c.classList.remove('active'));
  document.getElementById(`tab-${tab}`).classList.add('active');
  document.getElementById('addSegInd').style.transform = tab === 'auto' ? 'translateX(100%)' : 'translateX(0)';

  if (tab === 'manual') initManualForm();
  else initOcrForm();
}

// ---------- 手动 ----------
function initManualForm(flow) {
  if (flow) switchManualFlow(flow, true);
  // 编辑模式：表单重新初始化时保留正在编辑的账目（如从「拍一张」切回手动）
  if (editingTxId) {
    const t = getTransactions().find(x => x.id === editingTxId);
    if (t) { enterEditMode(t); return; }
    exitEditMode();
  }
  document.getElementById('manualDate').value = getTodayStr();
  document.getElementById('manualTime').value = getTimeStr();
  document.getElementById('manualAmount').value = '';
  document.getElementById('manualNote').value = '';
  selectedCategory = null;
  selectedSubcategory = null;
  document.getElementById('subcategorySection').hidden = true;

  renderCategoryGrid('categoryGrid', 'manual');
}

function switchManualFlow(flow, silent) {
  manualFlow = flow === 'income' ? 'income' : 'expense';
  document.querySelectorAll('#flowToggle button').forEach(b => {
    b.classList.toggle('active', b.dataset.flow === manualFlow);
  });
  document.getElementById('manualAmountLabel').textContent = manualFlow === 'income' ? '收入金额' : '金额';
  document.getElementById('manualSubmitBtn').textContent = editingTxId ? '保 存' : (manualFlow === 'income' ? '记 收 入' : '记 入');
  selectedCategory = null;
  selectedSubcategory = null;
  document.getElementById('subcategorySection').hidden = true;
  renderCategoryGrid('categoryGrid', 'manual');
}

function goExpenseEntry() {
  exitEditMode();
  navigateTo('add');
  switchManualFlow('expense');
}

function goIncomeEntry() {
  exitEditMode();
  navigateTo('add');
  switchManualFlow('income');
}

// 首页"拍一张"：进入拍照页，先确保媒体权限（部分 ROM 相册未授权显示为空）再弹出选图
function startPhotoAccounting() {
  navigateTo('add', 'auto');
  pickOcrImages();
}

async function pickOcrImages() {
  const p = window.Capacitor && window.Capacitor.Plugins && window.Capacitor.Plugins.SharedImport;
  // Android：走原生选图（WebView 的 file input 在异步授权后丢失手势会无响应）
  if (p && p.pickImages) {
    try {
      const r = await p.pickImages();
      const imgs = r && Array.isArray(r.images) ? r.images : [];
      if (!imgs.length) return; // 用户取消或未授权
      const files = imgs.map((im, i) => {
        const bin = atob(im.data);
        const arr = new Uint8Array(bin.length);
        for (let j = 0; j < bin.length; j++) arr[j] = bin.charCodeAt(j);
        return new File([arr], 'photo_' + i + '.jpg', { type: im.mime || 'image/jpeg' });
      });
      const input = document.getElementById('ocrFileInput');
      try { input.files = filesToDataTransfer(files).files; } catch (e) { /* 部分环境只读，忽略 */ }
      handleOcrFile({ target: { files } });
    } catch (e) {
      showToast((e && e.message) || '选择图片失败');
    }
    return;
  }
  // 浏览器预览：直接弹文件选择
  document.getElementById('ocrFileInput').click();
}

function filesToDataTransfer(files) {
  const dt = new DataTransfer();
  files.forEach(f => dt.items.add(f));
  return dt;
}

function renderCategoryGrid(containerId, ctx) {
  const cats = manualFlow === 'income' ? getIncomeCategories() : getCategories();
  const el = document.getElementById(containerId);
  el.innerHTML = cats.map(c => `
    <button class="cat-chip" data-cat="${c.name}" onclick="pickCategory('${c.name}','${ctx}')">
      <span class="cc-ico">${catIconHtml(c.icon, c.name)}</span>
      <span class="cc-name">${c.name}</span>
    </button>`).join('');
}

function markCatSelection(containerId, name) {
  document.querySelectorAll(`#${containerId} .cat-chip`).forEach(b => {
    b.classList.toggle('selected', b.dataset.cat === name);
  });
}

function pickCategory(name, ctx) {
  selectedCategory = name;
  selectedSubcategory = null;
  markCatSelection('categoryGrid', name);
  renderSubcategories(name);
}

function renderSubcategories(catName) {
  const cat = getCategories().find(c => c.name === catName);
  const sec = document.getElementById('subcategorySection');
  if (!cat || !cat.subcategories.length) { sec.hidden = true; return; }
  sec.hidden = false;
  document.getElementById('subcategoryList').innerHTML = cat.subcategories.map(s => `
    <button class="chip" onclick="pickSubcategory('${s}')">${s}</button>`).join('');
}

function pickSubcategory(name) {
  selectedSubcategory = name;
  document.querySelectorAll('#subcategoryList .chip').forEach(b => {
    b.classList.toggle('selected', b.textContent === name);
  });
}

function saveManualEntry() {
  const amount = parseFloat(document.getElementById('manualAmount').value);
  if (!amount || amount <= 0) return showToast('请输入金额');
  if (!selectedCategory) return showToast('请选择分类');

  const fields = {
    amount,
    category: selectedCategory,
    subcategory: selectedSubcategory || '',
    note: document.getElementById('manualNote').value.trim(),
    date: document.getElementById('manualDate').value,
    time: document.getElementById('manualTime').value,
    flow: manualFlow
  };

  // 编辑既有账目：原地更新，type/platform/items/createdAt 等原字段保持不变
  if (editingTxId) {
    const updated = updateTransaction(editingTxId, fields);
    const back = editReturnPage && editReturnPage !== 'add' ? editReturnPage : 'home';
    exitEditMode();
    showToast(updated ? '修改已保存' : '账目不存在，未保存');
    navigateTo(back);
    return;
  }

  addTransaction({ ...fields, type: 'manual' });

  showToast(manualFlow === 'income' ? '收入已记入' : '已记入账本');
  initManualForm(manualFlow);
  renderHome();
}

// ---------- 编辑既有账目 ----------
function enterEditMode(t, returnPage) {
  editingTxId = t.id;
  if (returnPage) editReturnPage = returnPage;
  switchManualFlow(t.flow === 'income' ? 'income' : 'expense', true);
  document.getElementById('manualAmount').value = t.amount;
  document.getElementById('manualDate').value = t.date || getTodayStr();
  document.getElementById('manualTime').value = t.time || '';
  document.getElementById('manualNote').value = t.note || '';
  selectedCategory = t.category || null;
  selectedSubcategory = t.subcategory || null;
  markCatSelection('categoryGrid', selectedCategory || '');
  renderSubcategories(selectedCategory || '');
  document.querySelectorAll('#subcategoryList .chip').forEach(b => {
    b.classList.toggle('selected', b.textContent === (t.subcategory || ''));
  });
  document.getElementById('editBanner').hidden = false;
}

function exitEditMode() {
  if (!editingTxId) return;
  editingTxId = null;
  editReturnPage = 'home';
  const banner = document.getElementById('editBanner');
  if (banner) banner.hidden = true;
}

function cancelEdit() {
  exitEditMode();
  initManualForm(manualFlow);
  showToast('已取消编辑');
}

// 从订单详情弹窗进入编辑：跳到记账页并回填表单
function startEditTx(id, returnPage) {
  const t = getTransactions().find(x => x.id === id);
  if (!t) return;
  // 先记住来源页（navigateTo('add') 会把 currentPage 覆盖为 'add'）
  const back = returnPage || (currentPage !== 'add' ? currentPage : 'home');
  closeTxDetail();
  navigateTo('add'); // 会重置表单；编辑态随后由 enterEditMode 建立
  enterEditMode(t, back);
}

// ---------- 拍照（多图自动识别流程）----------
function initOcrForm() {
  ocrQueue = [];
  ocrCards = [];
  ocrSheetOpen = false;
  document.getElementById('uploadEmpty').hidden = false;
  document.getElementById('uploadPreviewWrap').hidden = true;
  document.getElementById('scanStatus').textContent = '';
  document.getElementById('ocrFileInput').value = '';
  closeOcrSheet();
}

function handleOcrFile(e) {
  const files = Array.from(e.target.files || []);
  e.target.value = ''; // 允许重复选择同一文件
  if (!files.length) return;

  const readers = files.map(f => new Promise(res => {
    const r = new FileReader();
    r.onload = ev => res(ev.target.result);
    r.readAsDataURL(f);
  }));

  Promise.all(readers).then(datas => {
    datas.forEach(dataUrl => {
      ocrQueue.push({
        id: 'q' + Date.now().toString(36) + Math.random().toString(36).slice(2, 6),
        dataUrl, status: 'pending', results: null, error: ''
      });
    });
    document.getElementById('uploadEmpty').hidden = true;
    document.getElementById('uploadPreviewWrap').hidden = false;
    renderThumbGrid();
    updateScanStatus();
    ocrQueue.filter(q => q.status === 'pending').forEach(analyzeOne); // 并行识别
  });
}

async function analyzeOne(item) {
  item.status = 'running';
  renderThumbGrid();
  updateScanStatus();
  try {
    // ocrRecognize 返回订单数组（单笔则为长度1）
    item.results = await ocrRecognize(item.dataUrl);
    item.status = 'done';
  } catch (err) {
    item.status = 'error';
    item.error = err.message;
  }
  renderThumbGrid();
  updateScanStatus();
  maybeOpenSheet();
}

function renderThumbGrid() {
  const el = document.getElementById('thumbGrid');
  el.innerHTML = ocrQueue.map((q, i) => {
    const badge = q.status === 'running' ? '<span class="tb-badge running"></span>'
      : q.status === 'done' ? '<span class="tb-badge done">✓</span>'
      : q.status === 'error' ? '<span class="tb-badge error">✕</span>' : '';
    const tip = q.status === 'error' ? ' title="识别失败，点击重试"' : '';
    const click = q.status === 'error' ? ` onclick="retryOcrItem(${i})"` : '';
    return `<div class="thumb ${q.status}"${tip}${click}><img src="${q.dataUrl}" alt="">${badge}</div>`;
  }).join('');
}

function retryOcrItem(i) {
  const item = ocrQueue[i];
  if (!item || item.status !== 'error') return;
  analyzeOne(item);
}

function updateScanStatus() {
  const el = document.getElementById('scanStatus');
  const running = ocrQueue.filter(q => q.status === 'running' || q.status === 'pending').length;
  const done = ocrQueue.filter(q => q.status === 'done').length;
  const failed = ocrQueue.filter(q => q.status === 'error').length;
  if (running) el.textContent = `正在识别 ${done + failed}/${ocrQueue.length} …`;
  else if (failed && !done) el.textContent = '全部识别失败 · 点击缩略图重试';
  else if (failed) el.textContent = `识别完成 · ${failed} 张失败可点缩略图重试`;
  else el.textContent = `识别完成 · 共 ${done} 张`;
}

function maybeOpenSheet() {
  if (ocrQueue.some(q => q.status === 'pending' || q.status === 'running')) return; // 还有在识别的
  const okItems = ocrQueue.filter(q => q.status === 'done');
  if (!okItems.length) return;
  openOcrSheet(okItems);
}

// ---------- 结果弹层（多图 × 多笔订单展开）----------
function openOcrSheet(items) {
  const catNames = getCategories().map(c => c.name);

  ocrCards = [];
  items.forEach(q => {
    // 每张图可能识别出多笔订单，逐笔展开为独立卡片
    (Array.isArray(q.results) ? q.results : []).forEach(r => {
      // 分类只信模型返回的 category，不再按平台武断兜底
      const suggested = catNames.includes(r.category) ? r.category : '其他';
      ocrCards.push({
        thumb: q.dataUrl,
        platform: r.platform || '',
        amount: r.amount ?? '',
        date: r.date || getTodayStr(),
        time: r.time || getTimeStr(),
        category: suggested,
        items: (r.items || []).filter(Boolean),
        merchant: r.merchant || ''
      });
    });
  });

  renderOcrCards();
  updateOcrSummary();
  ocrSheetOpen = true;
  document.getElementById('ocrSheetMask').classList.add('show');
  document.getElementById('ocrSheet').classList.add('show');
}

function renderOcrCards() {
  const el = document.getElementById('ocrCards');
  const cats = getCategories();
  el.innerHTML = ocrCards.map((c, i) => `
    <div class="ocr-card">
      <div class="oc-head">
        <img class="oc-thumb" src="${c.thumb}" alt="">
        <span class="order-type-tag">${detectPlatform(c.platform) ? platformLogoHtml(c.platform, 'tag-logo') : ''}${escapeHtml(c.platform || '未识别')}</span>
        <button class="oc-del" onclick="removeOcrCard(${i})" title="放弃这一笔">✕</button>
      </div>
      <div class="oc-body">
        <div class="amount-display fig oc-amount">
          <span class="yen">¥</span>
          <input type="number" step="0.01" min="0" inputmode="decimal" value="${c.amount}"
                 oninput="updateOcrCard(${i},'amount',this.value)">
        </div>
        <div class="form-row">
          <div class="form-cell">
            <label>日期</label>
            <input type="date" value="${c.date}" oninput="updateOcrCard(${i},'date',this.value)">
          </div>
          <div class="form-cell">
            <label>时间</label>
            <input type="time" value="${c.time}" oninput="updateOcrCard(${i},'time',this.value)">
          </div>
        </div>
        <div class="oc-cats">
          ${cats.map(cat => `
            <button class="chip ${cat.name === c.category ? 'selected' : ''}"
                    onclick="pickOcrCardCat(${i},'${cat.name}')">${catIconHtml(cat.icon, cat.name)} ${cat.name}</button>`).join('')}
        </div>
        <div class="tag-list oc-items">
          ${c.items.length ? c.items.map(it => `<span class="tag">${escapeHtml(it)}</span>`).join('') : '<span class="muted">未识别到物品</span>'}
        </div>
        <input type="text" class="plain-input" maxlength="50" placeholder="备注（默认商家名）" value="${escapeHtml(c.merchant || '')}"
               oninput="updateOcrCard(${i},'merchant',this.value)">
      </div>
    </div>`).join('');
}

function updateOcrCard(i, field, value) {
  if (!ocrCards[i]) return;
  ocrCards[i][field] = value;
  updateOcrSummary();
}

function pickOcrCardCat(i, name) {
  if (!ocrCards[i]) return;
  ocrCards[i].category = name;
  renderOcrCards(); // 重渲染选中态
}

function removeOcrCard(i) {
  ocrCards.splice(i, 1);
  if (!ocrCards.length) { resetOcr(); return; }
  renderOcrCards();
  updateOcrSummary();
}

function updateOcrSummary() {
  const el = document.getElementById('ocrSummary');
  const valid = ocrCards.filter(c => parseFloat(c.amount) > 0);
  const total = valid.reduce((s, c) => s + parseFloat(c.amount), 0);
  el.textContent = `共 ${ocrCards.length} 笔 · 合计 ¥${fmtMoney(total)}`;
  document.getElementById('ocrSaveBtn').textContent = ocrCards.length > 1 ? `全部记入（${ocrCards.length}笔）` : '确认记入';
}

function closeOcrSheet() {
  ocrSheetOpen = false;
  document.getElementById('ocrSheetMask').classList.remove('show');
  document.getElementById('ocrSheet').classList.remove('show');
}

function saveOcrEntries() {
  const valid = ocrCards.filter(c => {
    const amt = parseFloat(c.amount);
    return amt > 0;
  });
  if (!valid.length) return showToast('没有可记入的账目（金额无效）');

  for (const c of valid) {
    addTransaction({
      amount: parseFloat(c.amount),
      category: c.category || '其他',
      subcategory: '',
      note: (c.merchant || '').trim(),
      date: c.date,
      time: c.time,
      type: 'auto',
      platform: c.platform,
      items: c.items || []
    });
  }

  closeOcrSheet();
  initOcrForm();
  renderHome();
  showToast(`已记入 ${valid.length} 笔账目`);
}

function resetOcr() {
  closeOcrSheet();
  initOcrForm();
}

// ============================================================
// 统计页
// ============================================================
function renderStats() {
  loadStatsData();
}

function switchStatsPeriod(period) {
  currentStatsPeriod = period;
  statsDate = new Date();
  document.querySelectorAll('#statsSeg button').forEach(b => {
    b.classList.toggle('active', b.dataset.period === period);
  });
  document.getElementById('statsDateNav').style.display = period === 'all' ? 'none' : 'flex';
  loadStatsData();
}

function changeStatsDate(delta) {
  if (currentStatsPeriod === 'day') statsDate.setDate(statsDate.getDate() + delta);
  else if (currentStatsPeriod === 'week') statsDate.setDate(statsDate.getDate() + delta * 7);
  else if (currentStatsPeriod === 'month') statsDate = addMonths(statsDate, delta);
  else if (currentStatsPeriod === 'year') statsDate.setFullYear(statsDate.getFullYear() + delta);
  loadStatsData();
}

// 安全加月份：固定为当月1号，避免 1/31 +1月 → 3/3 的越界漂移
function addMonths(d, n) {
  return new Date(d.getFullYear(), d.getMonth() + n, 1);
}

// 计算当前期与上期范围
function getPeriodRanges() {
  const p = currentStatsPeriod;
  const y = statsDate.getFullYear(), m = statsDate.getMonth() + 1;

  if (p === 'day') {
    const d = new Date(statsDate); d.setDate(d.getDate() - 1);
    return {
      cur: { start: formatDate(statsDate), end: formatDate(statsDate), days: 1, label: `${m}月${statsDate.getDate()}日支出` },
      prev: { start: formatDate(d), end: formatDate(d) }
    };
  }
  if (p === 'week') {
    const mon = getWeekMonday(statsDate);
    const sun = new Date(mon); sun.setDate(mon.getDate() + 6);
    const pMon = new Date(mon); pMon.setDate(mon.getDate() - 7);
    const pSun = new Date(sun); pSun.setDate(sun.getDate() - 7);
    return {
      cur: { start: formatDate(mon), end: formatDate(sun), days: 7, label: '本周支出' },
      prev: { start: formatDate(pMon), end: formatDate(pSun) }
    };
  }
  if (p === 'month') {
    const days = new Date(y, m, 0).getDate();
    const pm = m === 1 ? 12 : m - 1, py = m === 1 ? y - 1 : y;
    return {
      cur: { start: `${y}-${String(m).padStart(2, '0')}-01`, end: `${y}-${String(m).padStart(2, '0')}-${days}`, days, label: `${y}年${m}月支出` },
      prev: { start: `${py}-${String(pm).padStart(2, '0')}-01`, end: `${py}-${String(pm).padStart(2, '0')}-${new Date(py, pm, 0).getDate()}` }
    };
  }
  if (p === 'year') {
    const py = y - 1;
    return {
      cur: { start: `${y}-01-01`, end: `${y}-12-31`, days: (y % 4 === 0 && y % 100 !== 0) || y % 400 === 0 ? 366 : 365, label: `${y}年支出` },
      prev: { start: `${py}-01-01`, end: `${py}-12-31` }
    };
  }
  // 全部
  const all = getTransactions();
  if (!all.length) return { cur: { start: getTodayStr(), end: getTodayStr(), days: 1, label: '全部支出' }, prev: null };
  const dates = all.map(t => t.date).sort();
  const days = Math.max(1, Math.round((new Date(dates[dates.length - 1]) - new Date(dates[0])) / 86400000) + 1);
  return { cur: { start: dates[0], end: dates[dates.length - 1], days, label: '全部支出' }, prev: null };
}

function updateStatsDateDisplay(label) {
  const el = document.getElementById('statsDateDisplay');
  const p = currentStatsPeriod;
  if (p === 'day') {
    const v = formatDate(statsDate);
    el.textContent = v === getTodayStr() ? '今天' : `${statsDate.getMonth() + 1}月${statsDate.getDate()}日`;
  } else if (p === 'week') {
    const mon = getWeekMonday(statsDate);
    const sun = new Date(mon); sun.setDate(mon.getDate() + 6);
    el.textContent = `${mon.getMonth() + 1}.${mon.getDate()} — ${sun.getMonth() + 1}.${sun.getDate()}`;
  } else if (p === 'month') {
    el.textContent = `${statsDate.getFullYear()}年${statsDate.getMonth() + 1}月`;
  } else if (p === 'year') {
    el.textContent = `${statsDate.getFullYear()}年`;
  } else {
    el.textContent = label || '';
  }
}

function loadStatsData() {
  const { cur, prev } = getPeriodRanges();
  updateStatsDateDisplay();

  const allTx = getTransactionsByDateRange(cur.start, cur.end);
  const tx = allTx.filter(t => !isIncome(t));            // 支出
  const incomeTx = allTx.filter(isIncome);               // 收入
  const total = sumBy(tx, t => t.amount);
  const incomeTotal = sumBy(incomeTx, t => t.amount);

  // 概要（支出）
  document.getElementById('statsPeriodLabel').textContent = cur.label;
  document.getElementById('statsTotal').textContent = fmtMoney(total);
  document.getElementById('statsCount').textContent = tx.length;
  document.getElementById('statsAvg').textContent = '¥' + (tx.length ? Math.round(total / tx.length) : 0);
  document.getElementById('statsMax').textContent = '¥' + (tx.length ? Math.round(Math.max(...tx.map(t => t.amount))) : 0);
  document.getElementById('statsDailyAvg').textContent = '¥' + Math.round(total / cur.days);

  // 收入概览
  renderIncomePanel(incomeTx, incomeTotal, total);

  // 环比（支出）
  const chip = document.getElementById('statsCompare');
  if (prev) {
    const prevTotal = sumBy(getTransactionsByDateRange(prev.start, prev.end).filter(t => !isIncome(t)), t => t.amount);
    if (prevTotal === 0 && total === 0) { chip.hidden = true; }
    else if (prevTotal === 0) {
      chip.hidden = false; chip.className = 'compare-chip up'; chip.textContent = '▲ 较上期新增支出';
    } else {
      const pct = ((total - prevTotal) / prevTotal) * 100;
      chip.hidden = false;
      chip.className = 'compare-chip ' + (pct >= 0 ? 'up' : 'down');
      chip.textContent = `${pct >= 0 ? '▲' : '▼'} 较上期 ${Math.abs(pct).toFixed(1)}%`;
    }
  } else {
    chip.hidden = true;
  }

  drawDonut(tx);
  renderCategoryRank(tx, total);
  renderSubcatRank(tx);
  renderTimeDist(tx, total);
  drawTrend(tx);
  renderTypeDist(tx, total);
}

// ---------- 收入概览 ----------
function renderIncomePanel(incomeTx, incomeTotal, expenseTotal) {
  const card = document.getElementById('incomeCard');
  if (!incomeTx.length) { card.hidden = true; return; }
  card.hidden = false;

  document.getElementById('incomeTotal').textContent = '¥' + fmtMoney(incomeTotal);
  document.getElementById('incomeCount').textContent = incomeTx.length;
  document.getElementById('incomeAvg').textContent = '¥' + Math.round(incomeTotal / incomeTx.length);
  document.getElementById('incomeMax').textContent = '¥' + Math.round(Math.max(...incomeTx.map(t => t.amount)));
  document.getElementById('incomeNet').textContent = '¥' + Math.round(incomeTotal - expenseTotal);

  // 收入构成排行
  const map = {};
  incomeTx.forEach(t => { map[t.category] = (map[t.category] || 0) + t.amount; });
  const entries = Object.entries(map).sort((a, b) => b[1] - a[1]);
  const max = entries[0][1];
  const el = document.getElementById('incomeRank');
  el.innerHTML = entries.map(([cat, amt]) => `
    <div class="hbar-row">
      <div class="hbar-top">
        <span class="h-name">${getCategoryIcon(cat)} ${cat}</span>
        <span class="h-val income-val">¥${fmtMoney(amt)}<small>${incomeTotal ? (amt / incomeTotal * 100).toFixed(0) : 0}%</small></span>
      </div>
      <div class="hbar-track"><i class="income-bar" style="width:${(amt / max * 100).toFixed(1)}%"></i></div>
    </div>`).join('');
}

// ---------- 甜甜圈 ----------
function drawDonut(tx) {
  const canvas = document.getElementById('pieChart');
  const wrap = document.querySelector('.donut-wrap');
  const dpr = window.devicePixelRatio || 1;
  const size = Math.min(wrap.clientWidth || 200, 200);
  canvas.width = size * dpr;
  canvas.height = size * dpr;
  const ctx = canvas.getContext('2d');
  ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
  ctx.clearRect(0, 0, size, size);

  const catStats = calcCategoryStats(tx);
  const entries = Object.entries(catStats).sort((a, b) => b[1] - a[1]);
  const total = entries.reduce((s, e) => s + e[1], 0);

  // 图例
  const legend = document.getElementById('pieLegend');
  if (!total) {
    legend.innerHTML = '';
    ctx.fillStyle = cssVar('--ink-3', '#A49C8B');
    ctx.font = '13px sans-serif';
    ctx.textAlign = 'center';
    ctx.textBaseline = 'middle';
    ctx.fillText('暂无数据', size / 2, size / 2);
    return;
  }

  const cx = size / 2, cy = size / 2;
  const r = size * 0.42;
  const gap = 2.5 / (size * 0.42); // 弧间隙：约 2.5px，露出卡片底色做分隔（V4）
  let angle = -Math.PI / 2;

  entries.forEach(([cat, amount], i) => {
    const slice = (amount / total) * Math.PI * 2;
    const a0 = angle + gap / 2, a1 = angle + slice - gap / 2;
    if (a1 > a0) {
      ctx.beginPath();
      ctx.arc(cx, cy, r, a0, a1);
      ctx.strokeStyle = catColor(cat);
      ctx.lineWidth = size * 0.1;
      ctx.lineCap = 'butt';
      ctx.stroke();
    }
    angle += slice;
  });

  // 中心文字
  ctx.fillStyle = cssVar('--ink', '#26221A');
  ctx.font = `600 ${Math.round(size * 0.1)}px Georgia, serif`;
  ctx.textAlign = 'center';
  ctx.textBaseline = 'middle';
  ctx.fillText('¥' + Math.round(total), cx, cy - size * 0.035);
  ctx.fillStyle = cssVar('--ink-3', '#A49C8B');
  ctx.font = `${Math.round(size * 0.058)}px sans-serif`;
  ctx.fillText(`${entries.length} 个分类`, cx, cy + size * 0.075);

  legend.innerHTML = entries.map(([cat, amount], i) => `
    <span class="legend-item">
      <span class="legend-dot" style="background:${catColor(cat)}"></span>
      ${cat} <b>¥${Math.round(amount)}</b>
    </span>`).join('');
}

// ---------- 分类排行 ----------
function renderCategoryRank(tx, total) {
  const el = document.getElementById('categoryRank');
  const catStats = calcCategoryStats(tx);
  const entries = Object.entries(catStats).sort((a, b) => b[1] - a[1]);
  if (!entries.length) { el.innerHTML = emptyStateHtml('暂无数据', null, true); return; }
  const max = entries[0][1];

  el.innerHTML = entries.map(([cat, amount], i) => `
    <div class="rank-row">
      <span class="rank-no">${i + 1}</span>
      <div class="rank-main">
        <div class="rank-name"><span>${renderCatIcon(cat)} ${cat}</span><span class="r-amt">¥${fmtMoney(amount)}</span></div>
        <div class="rank-bar"><i style="width:${(amount / max * 100).toFixed(1)}%;background:${catColor(cat)}"></i></div>
        <div class="rank-extra">${total ? (amount / total * 100).toFixed(1) : 0}% · 占比</div>
      </div>
    </div>`).join('');
}

// ---------- 子分类 TOP5 ----------
function renderSubcatRank(tx) {
  const el = document.getElementById('subcatRank');
  const map = {};
  tx.forEach(t => {
    const key = t.subcategory || t.category;
    if (!map[key]) map[key] = { amount: 0, count: 0, cat: t.category };
    map[key].amount += t.amount;
    map[key].count++;
  });
  const entries = Object.entries(map).sort((a, b) => b[1].amount - a[1].amount).slice(0, 5);
  if (!entries.length) { el.innerHTML = emptyStateHtml('暂无数据', null, true); return; }
  const max = entries[0][1].amount;

  el.innerHTML = entries.map(([name, d], i) => `
    <div class="rank-row">
      <span class="rank-no">${i + 1}</span>
      <div class="rank-main">
        <div class="rank-name"><span>${name} <span class="muted">· ${d.cat}</span></span><span class="r-amt">¥${fmtMoney(d.amount)}</span></div>
        <div class="rank-bar"><i style="width:${(d.amount / max * 100).toFixed(1)}%"></i></div>
        <div class="rank-extra">${d.count} 笔</div>
      </div>
    </div>`).join('');
}

// ---------- 消费时段 ----------
function renderTimeDist(tx, total) {
  const el = document.getElementById('timeDist');
  const segs = TIME_SEGMENTS.map(s => ({ ...s, amount: 0, count: 0 }));
  tx.forEach(t => {
    const h = parseInt((t.time || '12:00').split(':')[0], 10) || 0;
    const seg = segs.find(s => h >= s.from && h < s.to);
    if (seg) { seg.amount += t.amount; seg.count++; }
  });
  const max = Math.max(...segs.map(s => s.amount));
  if (!total) { el.innerHTML = emptyStateHtml('暂无数据', null, true); return; }

  el.innerHTML = segs.map(s => `
    <div class="hbar-row">
      <div class="hbar-top">
        <span class="h-name">${s.name}</span>
        <span class="h-val">¥${fmtMoney(s.amount)}<small>${s.count} 笔${total ? ' · ' + (s.amount / total * 100).toFixed(0) + '%' : ''}</small></span>
      </div>
      <div class="hbar-track"><i style="width:${max ? (s.amount / max * 100).toFixed(1) : 0}%"></i></div>
    </div>`).join('');
}

// ---------- 记录方式 ----------
function renderTypeDist(tx, total) {
  const el = document.getElementById('typeDist');
  const manual = tx.filter(t => t.type !== 'auto');
  const auto = tx.filter(t => t.type === 'auto');
  const mAmt = manual.reduce((s, t) => s + t.amount, 0);
  const aAmt = auto.reduce((s, t) => s + t.amount, 0);
  const max = Math.max(mAmt, aAmt);
  if (!tx.length) { el.innerHTML = emptyStateHtml('暂无数据', null, true); return; }

  const row = (name, amt, count) => `
    <div class="hbar-row">
      <div class="hbar-top">
        <span class="h-name">${name}</span>
        <span class="h-val">¥${fmtMoney(amt)}<small>${count} 笔</small></span>
      </div>
      <div class="hbar-track"><i style="width:${max ? (amt / max * 100).toFixed(1) : 0}%"></i></div>
    </div>`;
  el.innerHTML = row('✍ 手动记账', mAmt, manual.length) + row('📷 拍照记账', aAmt, auto.length);
}

// ---------- 趋势图（自适应粒度）----------
function buildTrendData(tx) {
  const p = currentStatsPeriod;
  const daily = {};
  tx.forEach(t => { daily[t.date] = (daily[t.date] || 0) + t.amount; });

  if (p === 'day') {
    // 按小时聚合（每 2 小时一格）
    const slots = Array.from({ length: 12 }, (_, i) => ({ label: i * 2 + '时', value: 0 }));
    tx.forEach(t => {
      const h = parseInt((t.time || '12:00').split(':')[0], 10) || 0;
      slots[Math.floor(h / 2)].value += t.amount;
    });
    return { data: slots, unit: '按 2 小时' };
  }
  if (p === 'week') {
    const mon = getWeekMonday(statsDate);
    const days = [];
    for (let i = 0; i < 7; i++) {
      const d = new Date(mon); d.setDate(mon.getDate() + i);
      days.push({ label: WEEK_CN[d.getDay()], value: daily[formatDate(d)] || 0 });
    }
    return { data: days, unit: '按天' };
  }
  if (p === 'month') {
    const y = statsDate.getFullYear(), m = statsDate.getMonth() + 1;
    const daysInMonth = new Date(y, m, 0).getDate();
    const days = [];
    for (let d = 1; d <= daysInMonth; d++) {
      const key = `${y}-${String(m).padStart(2, '0')}-${String(d).padStart(2, '0')}`;
      days.push({ label: String(d), value: daily[key] || 0 });
    }
    return { data: days, unit: '按天' };
  }
  if (p === 'year') {
    const y = statsDate.getFullYear();
    const months = [];
    for (let m = 1; m <= 12; m++) {
      const amt = tx.filter(t => t.date.startsWith(`${y}-${String(m).padStart(2, '0')}`)).reduce((s, t) => s + t.amount, 0);
      months.push({ label: m + '月', value: amt });
    }
    return { data: months, unit: '按月' };
  }
  // 全部：按月聚合
  const monthMap = {};
  tx.forEach(t => {
    const key = t.date.slice(0, 7);
    monthMap[key] = (monthMap[key] || 0) + t.amount;
  });
  let keys = Object.keys(monthMap).sort();
  if (keys.length > 24) keys = keys.slice(-24);
  return { data: keys.map(k => ({ label: parseInt(k.slice(5, 7)) + '月', value: monthMap[k] })), unit: '按月' };
}

let trendLayout = null;  // 趋势图布局缓存（供悬停高亮重绘）
let trendHover = -1;     // 当前悬停的柱子下标，-1 表示无

function drawTrend(tx) {
  const { data, unit } = buildTrendData(tx);
  document.getElementById('trendUnit').textContent = unit;

  const canvas = document.getElementById('barChart');
  const wrap = document.querySelector('.chart-wrap');
  const dpr = window.devicePixelRatio || 1;
  const W = wrap.clientWidth || 320, H = 190;
  canvas.width = W * dpr;
  canvas.height = H * dpr;
  const ctx = canvas.getContext('2d');
  ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
  ctx.clearRect(0, 0, W, H);

  if (!tx.length) {
    trendLayout = null;
    ctx.fillStyle = cssVar('--ink-3', '#A49C8B');
    ctx.font = '13px sans-serif';
    ctx.textAlign = 'center';
    ctx.fillText('暂无数据', W / 2, H / 2);
    return;
  }

  const maxVal = Math.max(...data.map(d => d.value)) || 1;
  const pad = { top: 14, bottom: 22, left: 4, right: 4 };
  const cw = W - pad.left - pad.right;
  const ch = H - pad.top - pad.bottom;
  const n = data.length;
  const barW = Math.min((cw - (n - 1) * 3) / n, 26);
  const gap = (cw - barW * n) / (n + 1);
  const labelStep = Math.ceil(n / 7);

  trendLayout = {
    ctx, W, H, maxVal, barW, n, labelStep,
    bars: data.map((d, i) => ({
      ...d,
      x: pad.left + gap + i * (barW + gap),
      h: d.value > 0 ? Math.max((d.value / maxVal) * ch, 2) : 0
    }))
  };
  paintTrend();
  bindTrendHover();
}

// 绘制趋势柱图：悬停单日高亮并标注金额（V4）
function paintTrend() {
  const L = trendLayout;
  if (!L) return;
  const ctx = L.ctx;
  ctx.clearRect(0, 0, L.W, L.H);

  L.bars.forEach((d, i) => {
    const y = 14 + (L.H - 14 - 22) - d.h;
    if (d.value > 0) {
      ctx.fillStyle = (i === trendHover || d.value === L.maxVal)
        ? cssVar('--red', '#B93A21')
        : cssVar('--ink', '#26221A');
      if (ctx.roundRect) {
        ctx.beginPath();
        ctx.roundRect(d.x, y, L.barW, d.h, [3, 3, 0, 0]);
        ctx.fill();
      } else {
        ctx.fillRect(d.x, y, L.barW, d.h);
      }
    }
    if (i === trendHover && d.value > 0) {
      ctx.fillStyle = cssVar('--red', '#B93A21');
      ctx.font = '600 11px sans-serif';
      ctx.textAlign = 'center';
      ctx.fillText('¥' + Math.round(d.value), d.x + L.barW / 2, y - 5);
    }
    if (i % L.labelStep === 0 || i === L.n - 1) {
      ctx.fillStyle = cssVar('--ink-3', '#A49C8B');
      ctx.font = '10px sans-serif';
      ctx.textAlign = 'center';
      ctx.fillText(d.label, d.x + L.barW / 2, L.H - 6);
    }
  });
}

// 悬停/触摸高亮（只在首次绘制时绑定一次）
function bindTrendHover() {
  const canvas = document.getElementById('barChart');
  if (canvas.dataset.hoverBound) return;
  canvas.dataset.hoverBound = '1';
  canvas.addEventListener('pointermove', e => {
    if (!trendLayout) return;
    const rect = canvas.getBoundingClientRect();
    const x = (e.clientX - rect.left) * (trendLayout.W / rect.width);
    const idx = trendLayout.bars.findIndex(b => x >= b.x && x < b.x + trendLayout.barW);
    if (idx !== trendHover) { trendHover = idx; paintTrend(); }
  });
  canvas.addEventListener('pointerleave', () => {
    if (trendHover !== -1) { trendHover = -1; paintTrend(); }
  });
}

// ---------- 日历（明细页·逐日核对） ----------
function renderCalendar(year, month) {
  document.getElementById('calendarMonthDisplay').textContent = `${year}年${month}月`;

  const grid = document.getElementById('calendarGrid');
  const weekdays = ['一', '二', '三', '四', '五', '六', '日'];
  const firstDay = new Date(year, month - 1, 1).getDay();
  const startCol = firstDay === 0 ? 6 : firstDay - 1;
  const daysInMonth = new Date(year, month, 0).getDate();
  const prevMonth = month === 1 ? 12 : month - 1;
  const prevYear = month === 1 ? year - 1 : year;
  const prevDays = new Date(prevYear, prevMonth, 0).getDate();
  const today = getTodayStr();

  const monthTx = getTransactionsByMonth(year, month).filter(t => !isIncome(t));
  const dailyMap = {};
  monthTx.forEach(t => { dailyMap[t.date] = (dailyMap[t.date] || 0) + t.amount; });

  // 热力三档（V5）：当月单日支出最大值三等分，纸→赭金→朱砂
  const dayAmounts = Object.values(dailyMap);
  const maxDay = dayAmounts.length ? Math.max(...dayAmounts) : 0;
  const heatOf = amt => amt >= maxDay * 0.66 ? 'h3' : amt >= maxDay * 0.33 ? 'h2' : 'h1';

  let html = weekdays.map(w => `<div class="cal-week">${w}</div>`).join('');

  for (let i = prevDays - startCol + 1; i <= prevDays; i++) {
    html += `<div class="cal-day other"><span class="d-num">${i}</span></div>`;
  }
  for (let d = 1; d <= daysInMonth; d++) {
    const dateStr = `${year}-${String(month).padStart(2, '0')}-${String(d).padStart(2, '0')}`;
    const amt = dailyMap[dateStr];
    const cls = [dateStr === today ? 'today' : '', dateStr === billsDay ? 'sel' : '', amt ? heatOf(amt) : ''].filter(Boolean).join(' ');
    html += `
      <div class="cal-day ${cls}" onclick="selectCalendarDay('${dateStr}')">
        <span class="d-num">${d}</span>
        ${amt ? `<span class="d-amt">${Math.round(amt)}</span>` : ''}
      </div>`;
  }
  const totalCells = startCol + daysInMonth;
  const remaining = (7 - (totalCells % 7)) % 7;
  for (let i = 1; i <= remaining; i++) {
    html += `<div class="cal-day other"><span class="d-num">${i}</span></div>`;
  }
  grid.innerHTML = html;
}

// 点选日期 → 下方只列这一天的账目；再点同一天取消
function selectCalendarDay(dateStr) {
  billsDay = billsDay === dateStr ? null : dateStr;
  renderBills();
}

function clearCalendarDay() {
  billsDay = null;
  renderBills();
}

// ============================================================
// 明细页
// ============================================================
function changeBillsMonth(delta) {
  billsMonth = addMonths(billsMonth, delta);
  billsDay = null;   // 换月后回到整月视图，避免选中日期落在视野外
  renderBills();
}

// ---------- 搜索与筛选（明细页） ----------
const billsFilters = { flow: 'all', range: 'all', category: '', platform: '', min: null, max: null };
const FILTER_RANGE_DAYS = { m1: 30, m3: 90, y1: 365 };
let billsSearchTimer = null;

function billsSearchModeOn() {
  const q = (document.getElementById('billsSearchInput').value || '').trim();
  const f = billsFilters;
  return !!q || f.flow !== 'all' || f.range !== 'all' || !!f.category || !!f.platform || f.min != null || f.max != null;
}

function billsFiltersActive() {
  const f = billsFilters;
  return f.flow !== 'all' || f.range !== 'all' || !!f.category || !!f.platform || f.min != null || f.max != null;
}

// 平台归一：与流水展示口径一致（如「淘宝订单」归入「淘宝」）
function txPlatformKey(t) {
  return detectPlatform(t.platform) || (t.platform || '').trim();
}

function renderFilterChips() {
  const f = billsFilters;
  const chip = (kind, val, label, sel) =>
    `<button type="button" class="chip${sel ? ' selected' : ''}" data-kind="${kind}" data-val="${escapeHtml(val)}">${escapeHtml(label)}</button>`;

  document.getElementById('filterFlowChips').innerHTML =
    chip('flow', 'all', '全部', f.flow === 'all') +
    chip('flow', 'expense', '支出', f.flow === 'expense') +
    chip('flow', 'income', '收入', f.flow === 'income');

  document.getElementById('filterRangeChips').innerHTML =
    chip('range', 'all', '全部', f.range === 'all') +
    chip('range', 'm1', '近1月', f.range === 'm1') +
    chip('range', 'm3', '近3月', f.range === 'm3') +
    chip('range', 'y1', '近1年', f.range === 'y1');

  // 分类 / 平台选项从实际账目中归纳，只显示用得到的
  const all = getTransactions();
  const catCount = {}, platCount = {};
  all.forEach(t => {
    catCount[t.category] = (catCount[t.category] || 0) + 1;
    const p = txPlatformKey(t);
    if (p) platCount[p] = (platCount[p] || 0) + 1;
  });
  const cats = Object.keys(catCount).sort((a, b) => catCount[b] - catCount[a]);
  const KNOWN_PLATS = ['微信', '支付宝', '淘宝', '京东', '拼多多', '纸质小票'];
  const plats = Object.keys(platCount).sort((a, b) =>
    (KNOWN_PLATS.indexOf(a) + 1 || 99) - (KNOWN_PLATS.indexOf(b) + 1 || 99) || platCount[b] - platCount[a]);

  document.getElementById('filterCatGroup').style.display = cats.length ? '' : 'none';
  document.getElementById('filterCatChips').innerHTML =
    chip('category', '', '全部', !f.category) + cats.map(x => chip('category', x, x, f.category === x)).join('');

  document.getElementById('filterPlatformGroup').style.display = plats.length ? '' : 'none';
  document.getElementById('filterPlatformChips').innerHTML =
    chip('platform', '', '全部', !f.platform) + plats.map(x => chip('platform', x, x, f.platform === x)).join('');
}

function updateFilterUI() {
  const active = billsFiltersActive();
  document.getElementById('filterActiveDot').hidden = !active;
  document.getElementById('billsFilterBtn').classList.toggle('active', active);
}

function runBillsSearch() {
  const input = document.getElementById('billsSearchInput');
  const mode = billsSearchModeOn();
  document.getElementById('calendarCard').style.display = mode ? 'none' : '';
  document.getElementById('billsMonthSummary').style.display = mode ? 'none' : '';
  document.getElementById('billsSearchSummary').hidden = !mode;
  document.getElementById('billsSearchClear').hidden = !input.value;
  updateFilterUI();

  if (!mode) { renderBills(); return; }

  const q = input.value.trim().toLowerCase();
  const f = billsFilters;
  let tx = getTransactions();

  if (q) {
    // 关键词可空格分词，全部命中才保留；匹配备注/商家/分类/子分类/平台/物品
    const keys = q.split(/\s+/);
    tx = tx.filter(t => {
      const hay = [t.note, t.category, t.subcategory, t.platform, ...(t.items || [])]
        .filter(Boolean).join(' ').toLowerCase();
      return keys.every(k => hay.includes(k));
    });
  }
  if (f.flow !== 'all') tx = tx.filter(t => f.flow === 'income' ? isIncome(t) : !isIncome(t));
  if (f.category) tx = tx.filter(t => t.category === f.category);
  if (f.platform) tx = tx.filter(t => txPlatformKey(t) === f.platform);
  if (f.range !== 'all') {
    const cutoff = formatDate(new Date(Date.now() - FILTER_RANGE_DAYS[f.range] * 86400000));
    tx = tx.filter(t => t.date >= cutoff);
  }
  if (f.min != null) tx = tx.filter(t => t.amount >= f.min);
  if (f.max != null) tx = tx.filter(t => t.amount <= f.max);

  tx.sort((a, b) => (b.date + (b.time || '')).localeCompare(a.date + (a.time || '')));

  // 命中汇总
  const exp = sumBy(tx.filter(t => !isIncome(t)), t => t.amount);
  const inc = sumBy(tx.filter(isIncome), t => t.amount);
  document.getElementById('billsSearchSummary').innerHTML = `
    <span>共 <b class="fig">${tx.length}</b> 笔</span><i class="ss-div"></i>
    <span>支出 <b class="fig">¥${fmtMoney(exp)}</b></span>
    ${inc > 0 ? `<i class="ss-div"></i><span>收入 <b class="fig income-val">¥${fmtMoney(inc)}</b></span>` : ''}`;

  const list = document.getElementById('billsList');
  if (!tx.length) {
    list.innerHTML = `<div class="panel">${emptyStateHtml('没有匹配的账目，换个条件试试')}</div>`;
    return;
  }
  const groups = {};
  tx.forEach(t => { (groups[t.date] = groups[t.date] || []).push(t); });
  list.innerHTML = Object.keys(groups).sort((a, b) => b.localeCompare(a)).map(date => {
    const items = groups[date];
    const dayExpense = sumBy(items.filter(t => !isIncome(t)), t => t.amount);
    const dayIncome = sumBy(items.filter(isIncome), t => t.amount);
    const d = new Date(date + 'T00:00:00');
    return `
      <div class="day-group">
        <div class="day-head">
          <span>${d.getFullYear()}年${d.getMonth() + 1}月${d.getDate()}日 · 周${WEEK_CN[d.getDay()]}</span>
          <span class="d-amt">${dayIncome > 0 ? `<em class="income-val">+¥${fmtMoney(dayIncome)}</em> · ` : ''}¥${fmtMoney(dayExpense)}</span>
        </div>
        <div class="day-panel">
          ${items.map(t => txRowHtml(t, { deleteId: t.id, clickTitle: '长按删除', showType: true })).join('')}
        </div>
      </div>`;
  }).join('');
}

function toggleBillsFilter() {
  const panel = document.getElementById('billsFilterPanel');
  panel.hidden = !panel.hidden;
}

function resetBillsFilters() {
  Object.assign(billsFilters, { flow: 'all', range: 'all', category: '', platform: '', min: null, max: null });
  document.getElementById('filterAmountMin').value = '';
  document.getElementById('filterAmountMax').value = '';
  renderFilterChips();
  updateFilterUI();
  runBillsSearch();
}

function clearBillsSearchInput() {
  const input = document.getElementById('billsSearchInput');
  input.value = '';
  runBillsSearch();
  input.focus();
}

function bindBillsSearch() {
  const input = document.getElementById('billsSearchInput');
  input.addEventListener('input', () => {
    document.getElementById('billsSearchClear').hidden = !input.value;
    clearTimeout(billsSearchTimer);
    billsSearchTimer = setTimeout(runBillsSearch, 220);
  });
  input.addEventListener('keydown', e => {
    if (e.key === 'Enter') { e.preventDefault(); clearTimeout(billsSearchTimer); runBillsSearch(); input.blur(); }
  });
  ['filterAmountMin', 'filterAmountMax'].forEach(id => {
    document.getElementById(id).addEventListener('input', e => {
      const v = e.target.value.trim();
      const n = parseFloat(v);
      billsFilters[id === 'filterAmountMin' ? 'min' : 'max'] = (v === '' || isNaN(n)) ? null : n;
      clearTimeout(billsSearchTimer);
      billsSearchTimer = setTimeout(runBillsSearch, 300);
    });
  });
  // 筛选 chip 用事件委托，避免中文分类名拼进内联 onclick
  document.getElementById('billsFilterPanel').addEventListener('click', e => {
    const c2 = e.target.closest('.chip[data-kind]');
    if (!c2) return;
    const kind = c2.dataset.kind, val = c2.dataset.val;
    if (kind === 'flow') billsFilters.flow = val;
    else if (kind === 'range') billsFilters.range = val;
    else if (kind === 'category') billsFilters.category = val;
    else if (kind === 'platform') billsFilters.platform = val;
    renderFilterChips();
    updateFilterUI();
    runBillsSearch();
  });
}

function renderBills() {
  renderFilterChips();
  updateFilterUI();
  if (billsSearchModeOn()) { runBillsSearch(); return; }
  document.getElementById('calendarCard').style.display = '';
  document.getElementById('billsMonthSummary').style.display = '';
  document.getElementById('billsSearchSummary').hidden = true;

  const y = billsMonth.getFullYear(), m = billsMonth.getMonth() + 1;
  const monthTx = getTransactionsByMonth(y, m);
  const list = document.getElementById('billsList');
  renderCalendar(y, m);

  // 选中某天：只列该日账目（按时间倒序），汇总条显示当日收支
  if (billsDay) {
    const dayTx = monthTx.filter(t => t.date === billsDay)
      .sort((a, b) => (b.time || '').localeCompare(a.time || ''));
    renderBillsSummary(dayTx, true);
    list.innerHTML = dayTx.length
      ? `<div class="day-panel">${dayTx.map(t => txRowHtml(t, { deleteId: t.id, clickTitle: '长按删除', showType: true })).join('')}</div>`
      : `<div class="panel">${emptyStateHtml('这天没有账目', '记一笔')}</div>`;
    return;
  }

  const tx = monthTx.sort((a, b) => (b.date + (b.time || '')).localeCompare(a.date + (a.time || '')));
  renderBillsSummary(tx, false);
  if (!tx.length) {
    list.innerHTML = `<div class="panel">${emptyStateHtml('本月暂无账目，记一笔？', '记一笔')}</div>`;
    return;
  }

  // 按日期分组
  const groups = {};
  tx.forEach(t => { (groups[t.date] = groups[t.date] || []).push(t); });

  list.innerHTML = Object.keys(groups).sort((a, b) => b.localeCompare(a)).map(date => {
    const items = groups[date];
    const dayExpense = sumBy(items.filter(t => !isIncome(t)), t => t.amount);
    const dayIncome = sumBy(items.filter(isIncome), t => t.amount);
    const d = new Date(date + 'T00:00:00');
    return `
      <div class="day-group">
        <div class="day-head">
          <span>${d.getMonth() + 1}月${d.getDate()}日 · 周${WEEK_CN[d.getDay()]}</span>
          <span class="d-amt">${dayIncome > 0 ? `<em class="income-val">+¥${fmtMoney(dayIncome)}</em> · ` : ''}¥${fmtMoney(dayExpense)}</span>
        </div>
        <div class="day-panel">
          ${items.map(t => txRowHtml(t, { deleteId: t.id, clickTitle: '长按删除', showType: true })).join('')}
        </div>
      </div>`;
  }).join('');
}

// 汇总条：整月视图显示本月合计，选中日期时显示当日合计 + 「看整月」返回
function renderBillsSummary(tx, isDay) {
  const exp = sumBy(tx.filter(t => !isIncome(t)), t => t.amount);
  const inc = sumBy(tx.filter(isIncome), t => t.amount);
  const d = isDay ? new Date(billsDay + 'T00:00:00') : null;
  const parts = [d ? `${d.getMonth() + 1}月${d.getDate()}日 · 周${WEEK_CN[d.getDay()]}` : '本月'];
  parts.push(`共 <b class="fig">${tx.length}</b> 笔`);
  parts.push(`支出 <b class="fig">¥${fmtMoney(exp)}</b>`);
  if (inc > 0) parts.push(`收入 <b class="fig income-val">¥${fmtMoney(inc)}</b>`);

  const el = document.getElementById('billsMonthSummary');
  el.innerHTML = parts.map(p => `<span>${p}</span>`).join('<i class="ss-div"></i>')
    + (isDay ? '<button type="button" class="ms-clear" onclick="clearCalendarDay()">看整月</button>' : '');
}

// 长按删除：按住 550ms 触发，滑动/松开取消，防止误触
function bindBillsLongPress() {
  const list = document.getElementById('billsList');
  const LONG_PRESS_MS = 550, MOVE_TOLERANCE = 10;
  let timer = null, startX = 0, startY = 0, row = null;

  const clear = () => {
    if (timer) { clearTimeout(timer); timer = null; }
    if (row) { row.classList.remove('pressing'); row = null; }
  };

  list.addEventListener('pointerdown', e => {
    row = e.target.closest('.tx-row[data-del]');
    if (!row) return;
    startX = e.clientX; startY = e.clientY;
    row.classList.add('pressing');
    timer = setTimeout(() => {
      const r = row;
      clear();
      suppressTxClick = true; // 长按删除后不再触发点击详情
      setTimeout(() => { suppressTxClick = false; }, 600); // 兜底：若无后续 click，自动恢复
      if (r) deleteBill(r.dataset.del);
    }, LONG_PRESS_MS);
  });
  list.addEventListener('pointermove', e => {
    if (timer && (Math.abs(e.clientX - startX) > MOVE_TOLERANCE || Math.abs(e.clientY - startY) > MOVE_TOLERANCE)) clear();
  }, { passive: true });
  list.addEventListener('pointerup', clear);
  list.addEventListener('pointercancel', clear);
  list.addEventListener('pointerleave', clear);
}

async function deleteBill(id) {
  const ok = await uiConfirm('删除账目', '删除这笔账目？', '删除', true);
  if (!ok) return;
  deleteTransaction(id);
  renderBills();
  renderHome();
  showToast('已删除');
}

// ---------- 订单详情弹窗 ----------
let suppressTxClick = false;

// 点击任意账单行弹出详情（长按删除的行会跳过本次点击）
document.addEventListener('click', e => {
  const row = e.target.closest('.tx-row[data-tx]');
  if (!row) return;
  if (suppressTxClick) { suppressTxClick = false; return; }
  showTxDetail(row.dataset.tx);
}, true);

function showTxDetail(id) {
  const t = getTransactions().find(x => x.id === id);
  if (!t) return;
  const income = isIncome(t);
  const ico = t.platform ? platformLogoHtml(t.platform, 'detail-logo') : `<span class="detail-cat-icon">${renderCatIcon(t.category)}</span>`;
  const rows = [
    ['分类', `${escapeHtml(t.category)}${t.subcategory ? ' · ' + escapeHtml(t.subcategory) : ''}`],
    ['平台', t.platform ? escapeHtml(t.platform) : ''],
    ['日期', `${escapeHtml(t.date)} ${escapeHtml(t.time || '')}`],
    ['记录方式', t.type === 'auto' ? '📷 拍照识别' : '✍️ 手动记录'],
  ];
  const infoHtml = rows.filter(r => r[1])
    .map(r => `<div class="td-row"><span class="td-label">${r[0]}</span><span class="td-val">${r[1]}</span></div>`)
    .join('');
  const itemsHtml = t.items && t.items.length
    ? `<div class="td-items">${t.items.map(it => `<span class="tag">${escapeHtml(it)}</span>`).join('')}</div>` : '';
  document.getElementById('txDetailBody').innerHTML = `
    <div class="td-head">
      ${ico}
      <div class="td-head-main">
        <div class="td-amount fig ${income ? 'income-val' : ''}">${income ? '+' : '-'}¥${fmtMoney(t.amount)}</div>
        <div class="td-sub">${escapeHtml(t.category)}${t.subcategory ? ' · ' + escapeHtml(t.subcategory) : ''}</div>
      </div>
    </div>
    ${infoHtml}
    ${itemsHtml}
    ${t.note ? `<div class="td-note">${escapeHtml(t.note)}</div>` : ''}
    <div class="td-actions">
      <button class="btn-ghost" onclick="closeTxDetail()">关 闭</button>
      <button class="btn-solid" onclick="startEditTx('${t.id}')">编 辑</button>
    </div>`;
  document.getElementById('txDetailMask').classList.add('show');
  document.getElementById('txDetailModal').classList.add('show');
}

function closeTxDetail() {
  document.getElementById('txDetailMask').classList.remove('show');
  document.getElementById('txDetailModal').classList.remove('show');
}

