// 设置页
// ============================================================
// ---------- 通用确认弹窗（Capacitor WebView 不支持 confirm/prompt，全部用应用内弹窗） ----------
function uiConfirm(title, msg, okText, danger) {
  okText = okText || '确定';
  return new Promise(resolve => {
    const mask = document.createElement('div');
    mask.className = 'modal-mask show';
    mask.innerHTML = `
      <div class="dlg" role="dialog">
        <div class="dlg-title">${escapeHtml(title)}</div>
        ${msg ? `<div class="dlg-msg">${escapeHtml(msg)}</div>` : ''}
        <div class="dlg-btns">
          <button class="dlg-btn" data-act="no">取消</button>
          <button class="dlg-btn ${danger ? 'dlg-danger' : 'dlg-ok'}" data-act="yes">${escapeHtml(okText)}</button>
        </div>
      </div>`;
    const close = yes => {
      mask.classList.remove('show');
      setTimeout(() => mask.remove(), 180);
      resolve(!!yes);
    };
    mask.addEventListener('click', e => {
      const act = e.target.dataset && e.target.dataset.act;
      if (act === 'yes') close(true);
      else if (act === 'no' || e.target === mask) close(false);
    });
    document.body.appendChild(mask);
  });
}

// ---------- 分类编辑弹窗（新增/编辑两用）：返回 {name, icon, subcategories} 或 null ----------
function uiCategoryDialog(cat) {
  // 图标选择：定制 SVG 图标集（V1），兼容旧数据的 Emoji 图标（追加为附加选项）
  const legacyEmojis = [...new Set([cat && cat.icon].concat(getCategories().map(c => c.icon), getIncomeCategories().map(c => c.icon))
    .filter(ic => ic && !CATEGORY_ICON_SET[ic]))];
  const ICON_CHOICES = Object.keys(CATEGORY_ICON_SET).concat(legacyEmojis);
  // 初始选中：icon id 命中直接用；否则按分类名映射到默认图标 id
  const initialIcon = cat && CATEGORY_ICON_SET[cat.icon] ? cat.icon
    : (cat && Object.keys(CATEGORY_ICON_SET).find(id => CATEGORY_ICON_SET[id].name === cat.name)) || 'misc';
  const isNew = !cat;
  return new Promise(resolve => {
    const state = {
      name: (cat && cat.name) || '',
      icon: initialIcon,
      subs: (cat && Array.isArray(cat.subcategories) ? [...cat.subcategories] : [])
    };
    const mask = document.createElement('div');
    mask.className = 'modal-mask show';
    mask.innerHTML = `
      <div class="dlg dlg-cat" role="dialog">
        <div class="dlg-title">${isNew ? '添加分类' : '编辑分类'}</div>
        <div class="dlg-field">
          <label>图标</label>
          <div class="dlg-icons" id="dlgIcons">
            ${ICON_CHOICES.map(ic => {
              const svg = CATEGORY_ICON_SET[ic] ? CATEGORY_ICON_SET[ic].svg : escapeHtml(ic);
              return `<button type="button" class="dlg-ico${ic === state.icon ? ' sel' : ''}" data-ico="${ic}">${svg}</button>`;
            }).join('')}
          </div>
        </div>
        <div class="dlg-field">
          <label>名称</label>
          <input type="text" id="dlgCatName" maxlength="6" placeholder="如：餐饮" value="${escapeHtml(state.name)}">
        </div>
        <div class="dlg-field">
          <label>子分类（${state.subs.length}）</label>
          <div class="dlg-subs" id="dlgSubs"></div>
          <div class="dlg-sub-add">
            <input type="text" id="dlgSubInput" maxlength="10" placeholder="输入子分类">
            <button type="button" class="dlg-btn dlg-ok" id="dlgSubAdd">添加</button>
          </div>
        </div>
        <div class="dlg-btns">
          <button class="dlg-btn" data-act="no">取消</button>
          <button class="dlg-btn dlg-ok" data-act="yes">${isNew ? '添加' : '保存'}</button>
        </div>
      </div>`;
    const renderSubs = () => {
      const el = mask.querySelector('#dlgSubs');
      el.innerHTML = state.subs.length
        ? state.subs.map((s, i) => `<span class="dlg-chip">${escapeHtml(s)}<i data-sub="${i}">✕</i></span>`).join('')
        : '<span class="muted">暂无</span>';
    };
    renderSubs();
    mask.addEventListener('click', e => {
      const ico = e.target.closest('[data-ico]');
      if (ico) {
        state.icon = ico.dataset.ico;
        mask.querySelectorAll('.dlg-ico').forEach(b => b.classList.toggle('sel', b === ico));
        return;
      }
      const subDel = e.target.closest('[data-sub]');
      if (subDel) {
        state.subs.splice(+subDel.dataset.sub, 1);
        renderSubs();
        return;
      }
      if (e.target.id === 'dlgSubAdd') {
        const inp = mask.querySelector('#dlgSubInput');
        const v = inp.value.trim();
        if (v && !state.subs.includes(v)) { state.subs.push(v); renderSubs(); }
        inp.value = '';
        return;
      }
      const act = e.target.dataset && e.target.dataset.act;
      if (act === 'no' || e.target === mask) {
        mask.classList.remove('show'); setTimeout(() => mask.remove(), 180);
        resolve(null);
      } else if (act === 'yes') {
        const name = mask.querySelector('#dlgCatName').value.trim();
        if (!name) { showToast('请填写分类名称'); return; }
        mask.classList.remove('show'); setTimeout(() => mask.remove(), 180);
        resolve({ name, icon: state.icon, subcategories: state.subs });
      }
    });
    mask.addEventListener('keydown', e => {
      if (e.target.id === 'dlgSubInput' && e.key === 'Enter') { e.preventDefault(); mask.querySelector('#dlgSubAdd').click(); }
    });
    document.body.appendChild(mask);
    setTimeout(() => mask.querySelector('#dlgCatName').focus(), 120);
  });
}

function renderSettings() {
  const s = getApiSettings();
  document.getElementById('settingsApiUrl').value = s.url || '';
  document.getElementById('settingsApiKey').value = s.key || '';
  document.getElementById('settingsModel').value = s.model || '';
  document.getElementById('settingsPrompt').value = getOcrPrompt() || DEFAULT_OCR_PROMPT;
  renderCategorySettings();
  syncThemeUI(getThemePref());
}

function renderCategorySettings() {
  const el = document.getElementById('settingsCategories');
  el.innerHTML = getCategories().map((c, i) => `
    <div class="settings-cat" onclick="editCategory(${i})">
      <span class="sc-ico">${catIconHtml(c.icon, c.name)}</span>
      <span class="sc-name">${escapeHtml(c.name)}</span>
      <span class="sc-sub">${escapeHtml(c.subcategories.join('、')) || '—'}</span>
      <button class="sc-del" onclick="event.stopPropagation();removeCategory(${i})">✕</button>
    </div>`).join('');
}

function saveApiSettings() {
  saveApiSettingsToStorage({
    url: document.getElementById('settingsApiUrl').value.trim(),
    key: document.getElementById('settingsApiKey').value.trim(),
    model: document.getElementById('settingsModel').value.trim()
  });
  saveOcrPrompt(document.getElementById('settingsPrompt').value);
  showToast('配置已保存');
}

function toggleApiKeyVisible() {
  const inp = document.getElementById('settingsApiKey');
  const eye = document.getElementById('apiKeyEye');
  const show = inp.type === 'password';
  inp.type = show ? 'text' : 'password';
  eye.textContent = show ? '🙈' : '👁';
}

// 测试识图 API 连通性：发送 1 条最小文本请求验证 URL / Key / 模型
async function testApiConnection() {
  const url = document.getElementById('settingsApiUrl').value.trim();
  const key = document.getElementById('settingsApiKey').value.trim();
  const model = document.getElementById('settingsModel').value.trim();
  if (!url || !key) return showToast('请先填写 API 地址和 Key');

  const btn = document.getElementById('testConnBtn');
  btn.disabled = true; btn.textContent = '测试中…';
  try {
    const res = await fetch(url, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json', 'Authorization': `Bearer ${key}` },
      body: JSON.stringify({ model: model || 'glm-4.6v', messages: [{ role: 'user', content: 'hi' }], max_tokens: 4 })
    });
    if (res.ok) {
      showToast('✓ 连接成功，模型可用');
    } else {
      let tip = `HTTP ${res.status}`;
      try {
        const j = await res.json();
        if (j.error && j.error.message) tip += '：' + j.error.message.slice(0, 60);
      } catch (e) { /* 忽略非 JSON 响应 */ }
      showToast(`✗ 连接失败（${tip}）`);
    }
  } catch (e) {
    showToast('✗ 网络错误：' + (e.message || '无法访问该地址'));
  } finally {
    btn.disabled = false; btn.textContent = '测试连接';
  }
}

async function addCategory() {
  const result = await uiCategoryDialog(null);
  if (!result) return;
  const cats = getCategories();
  if (cats.some(c => c.name === result.name)) return showToast('分类已存在');
  cats.push(result);
  saveCategories(cats);
  renderCategorySettings();
  showToast('已添加');
}

function editCategory(index) {
  const cats = getCategories();
  uiCategoryDialog(cats[index]).then(result => {
    if (!result) return;
    cats[index] = result;
    saveCategories(cats);
    renderCategorySettings();
    showToast('已保存');
  });
}

async function removeCategory(index) {
  const cats = getCategories();
  if (cats.length <= 1) return showToast('至少保留一个分类');
  const used = getTransactions().some(t => t.category === cats[index].name);
  const ok = await uiConfirm('删除分类', `删除分类「${cats[index].name}」？${used ? '该分类下已有账目，删除后这些账目分类将显示为原文字。' : ''}`, '删除', true);
  if (!ok) return;
  cats.splice(index, 1);
  saveCategories(cats);
  renderCategorySettings();
  showToast('已删除');
}

async function clearAllData() {
  const ok = await uiConfirm('清除全部账目', '将删除本机所有账目记录，此操作不可恢复！', '全部清除', true);
  if (!ok) return;
  clearAllTransactions();
  renderHome();
  renderBills();
  if (currentPage === 'stats') loadStatsData();
  showToast('账目已清空');
}

// ============================================================
// JSON 导入（设置页选文件 / 系统分享给 APP 均走这里）
// ============================================================
function normalizeImportedTx(t) {
  const amount = parseFloat(t.amount);
  if (!(amount > 0) || !/^\d{4}-\d{2}-\d{2}$/.test(t.date || '')) return null;
  return {
    id: t.id || '',
    amount,
    category: t.category || '其他',
    subcategory: t.subcategory || '',
    note: t.note || '',
    date: t.date,
    time: t.time || '',
    type: t.type || 'manual',
    flow: t.flow === 'income' ? 'income' : 'expense',
    platform: t.platform || '',
    items: Array.isArray(t.items) ? t.items : [],
    createdAt: t.createdAt || Date.now()
  };
}

function mergeCategoriesByName(list, getter, saver) {
  if (!Array.isArray(list)) return 0;
  const current = getter();
  const names = new Set(current.map(c => c.name));
  const add = list.filter(c => c && c.name && !names.has(c.name))
    .map(c => ({ name: c.name, icon: c.icon || 'misc', subcategories: Array.isArray(c.subcategories) ? c.subcategories : [] }));
  if (add.length) saver([...current, ...add]);
  return add.length;
}

async function importJsonText(text) {
  let data;
  try { data = JSON.parse(text); }
  catch (e) { showToast('导入失败：JSON 格式无效'); return false; }

  // 兼容两种形态：完整导出对象 {transactions,...} / 纯账目数组
  const raw = Array.isArray(data) ? data : (Array.isArray(data.transactions) ? data.transactions : null);
  if (!raw) { showToast('导入失败：未找到账目数据'); return false; }

  const valid = raw.map(normalizeImportedTx).filter(Boolean);
  if (!valid.length) { showToast('导入失败：没有有效的账目'); return false; }

  const existing = getTransactions();
  if (existing.length) {
    const ok = await uiConfirm('导入账目', `检测到 ${valid.length} 笔账目，将合并导入（重复记录自动跳过）。继续？`, '导入');
    if (!ok) return false;
  }

  const ids = new Set(existing.map(t => t.id));
  const fresh = [];
  for (const t of valid) {
    if (t.id && ids.has(t.id)) continue; // 重复记录跳过
    t.id = t.id || ('i' + Date.now().toString(36) + Math.random().toString(36).slice(2, 8));
    ids.add(t.id);
    fresh.push(t);
  }
  if (!fresh.length) { showToast('没有新账目（全部与现有记录重复）'); return false; }

  saveTransactions([...fresh, ...existing]);

  // 分类一并合并（可选字段，老版本导出无此字段）
  if (!Array.isArray(data)) {
    mergeCategoriesByName(data.categories, getCategories, saveCategories);
    mergeCategoriesByName(data.incomeCategories, getIncomeCategories, saveIncomeCategories);
  }

  renderHome();
  renderBills();
  if (currentPage === 'stats') loadStatsData();
  if (currentPage === 'settings') renderCategorySettings();
  showToast(`已导入 ${fresh.length} 笔账目`);
  return true;
}

function handleImportFile(e) {
  const file = e.target.files && e.target.files[0];
  e.target.value = ''; // 允许重复选择同一文件
  if (!file) return;
  const reader = new FileReader();
  reader.onload = ev => importJsonText(ev.target.result);
  reader.onerror = () => showToast('读取文件失败');
  reader.readAsText(file, 'utf-8');
}

// ===== 系统分享导入（Capacitor 原生回调）=====
// Android 端收到 ACTION_SEND/VIEW 的 JSON 后会调用 window.__onSharedJson(text)
window.__onSharedJson = function (text) {
  if (importJsonText(String(text || ''))) navigateTo('bills'); // 成功后跳明细页查看
};

// Android 端收到系统分享的图片（相册→发送→简记）后调用 window.__onSharedImage()
window.__onSharedImage = function () {
  const p = window.Capacitor && window.Capacitor.Plugins && window.Capacitor.Plugins.SharedImport;
  if (!p || !p.readPendingImage) return;
  p.readPendingImage().then(r => {
    if (!r || !r.data) return;
    const bin = atob(r.data);
    const arr = new Uint8Array(bin.length);
    for (let i = 0; i < bin.length; i++) arr[i] = bin.charCodeAt(i);
    const file = new File([arr], 'shared.jpg', { type: r.mime || 'image/jpeg' });
    navigateTo('add', 'auto');
    handleOcrFile({ target: { files: [file] } });
    showToast('已接收分享的图片');
  }).catch(() => {});
};

// 冷启动时原生先于页面加载收到分享 → 拉取暂存数据（带重试，等插件注册完成）
function initSharedImport(attempt) {
  attempt = attempt || 0;
  const p = window.Capacitor && window.Capacitor.Plugins && window.Capacitor.Plugins.SharedImport;
  if (!p) {
    if (attempt < 6) setTimeout(() => initSharedImport(attempt + 1), 500);
    return;
  }
  p.takePending().then(r => {
    if (r && r.json) window.__onSharedJson(r.json);
    else if (r && r.imagePath) window.__onSharedImage();
  }).catch(() => {});
}

// ============================================================
// Android 桌面小组件 & 快捷方式
// ============================================================
// 把首页统计推给原生（写入 SharedPreferences 并刷新桌面小组件）
function pushWidgetStats() {
  const p = window.Capacitor && window.Capacitor.Plugins && window.Capacitor.Plugins.WidgetBridge;
  if (!p || !p.updateStats) return;
  const today = getTodayStr();
  const now = new Date();
  const monthTx = getTransactionsByMonth(now.getFullYear(), now.getMonth() + 1);
  const payload = {
    todayExpense: sumBy(getTransactionsByDate(today).filter(t => !isIncome(t)), t => t.amount),
    monthExpense: sumBy(monthTx.filter(t => !isIncome(t)), t => t.amount),
    monthIncome: sumBy(monthTx.filter(isIncome), t => t.amount),
    monthLabel: `${now.getMonth() + 1}月`,
    theme: currentTheme()
  };
  p.updateStats(payload).catch(() => {});
}

// 原生快捷方式（长按图标 → 记一笔 / 拍一张）拉起后回调
window.__onShortcut = function (action) {
  if (action === 'photo') startPhotoAccounting();
  else goExpenseEntry();
};

// 冷启动时原生先于页面收到快捷方式 → 拉取暂存动作（带重试，等插件注册完成）
function initShortcut(attempt) {
  attempt = attempt || 0;
  const p = window.Capacitor && window.Capacitor.Plugins && window.Capacitor.Plugins.WidgetBridge;
  if (!p || !p.takeShortcut) {
    if (attempt < 6) setTimeout(() => initShortcut(attempt + 1), 500);
    return;
  }
  p.takeShortcut().then(r => {
    if (r && r.action) window.__onShortcut(r.action);
  }).catch(() => {});
}

