function getWeekMonday(d) {
  const date = new Date(d);
  const day = date.getDay();
  date.setDate(date.getDate() - day + (day === 0 ? -6 : 1));
  return date;
}

document.addEventListener('DOMContentLoaded', () => {
  // 顶栏日期
  const now = new Date();
  document.getElementById('headerCaption').textContent =
    `${now.getMonth() + 1}月${now.getDate()}日 · 周${WEEK_CN[now.getDay()]}`;

  initTheme();         // 主题需先于图表渲染生效
  renderHome();
  initManualForm();
  renderBills();
  loadStatsData();
  bindBillsLongPress();
  bindBillsSearch();
  initSharedImport(); // Capacitor 环境：拉取分享进来的 JSON
  initShortcut();     // Capacitor 环境：拉取冷启动时的快捷方式动作
  setTimeout(pushWidgetStats, 800); // 插件注册完成后补推一次小组件数据

  // 窗口尺寸变化时重绘图表
  let resizeTimer;
  window.addEventListener('resize', () => {
    clearTimeout(resizeTimer);
    resizeTimer = setTimeout(() => {
      if (currentPage === 'stats') loadStatsData();
    }, 200);
  });
});
